		private static List<Condition> ToConditions(RLConditionRecordList list) {
			if (list == null) return new List<Condition>();
			return new List<Condition>(list.ToArray(r => new Condition {
				Path = r.ssSTCondition.ssPath,
				Operator = r.ssSTCondition.ssOperator,
				Value = r.ssSTCondition.ssValue,
				CaseSensitive = r.ssSTCondition.ssCaseSensitive
			}));
		}

		private static List<string> ToStrings(RLTextItemRecordList list) {
			if (list == null) return new List<string>();
			return new List<string>(list.ToArray(r => r.ssSTTextItem.ssValue));
		}

		private static RLTextItemRecordList ToTextItems(List<string> items) {
			var list = new RLTextItemRecordList();
			if (items == null) return list;
			foreach (var s in items) {
				var rec = new RCTextItemRecord(null);
				var st = new STTextItemStructure(null);
				st.ssValue = s ?? "";
				rec.ssSTTextItem = st;
				list.Add(rec);
			}
			return list;
		}
